INSERT INTO pak_lifecycle_rules (rule_key,rule_value) VALUES ('label_sets',CAST('{"young": {"max_age": 4, "good": "Fix Today", "better": "Fix + Peace of Mind", "best": "Full Service"}, "mid": {"max_age": 8, "good": "Fix Today", "better": "Fix + Prevent Next Failure", "best": "Consider Replacing"}, "old": {"max_age": 12, "good": "Temporary Fix", "better": "Repair + Extend Life", "best": "Replace Now"}, "end_life": {"max_age": 99, "good": "Emergency Fix", "better": "Last Repair", "best": "Replace Immediately"}}' AS jsonb));
INSERT INTO pak_lifecycle_rules (rule_key,rule_value) VALUES ('pakistan_note',CAST('Units age faster in Pakistan due to extreme heat (45-52C ambient), voltage fluctuations, and dust. Adjust thresholds accordingly.' AS jsonb));
INSERT INTO pak_data_defaults (market,refrigerant_by_year,cap_uf_by_tonnage,electrical_by_tonnage,tech_warning,inverter_note) VALUES ('Pakistan National (All 4 Provinces + ICT)',CAST('{"2023_plus": {"refrigerant": "R-32", "confidence_pct": 65}, "2015_to_2022": {"refrigerant": "R-410A", "confidence_pct": 72}, "2007_to_2014": {"refrigerant": "R-22", "confidence_pct": 78}, "pre_2007": {"refrigerant": "R-22", "confidence_pct": 91}}' AS jsonb),CAST('{"1.0": {"compressor_uf": 25, "fan_uf": 1.5, "voltage_rating": 450, "confidence_pct": 72}, "1.5": {"compressor_uf": 35, "fan_uf": 2.5, "voltage_rating": 450, "confidence_pct": 74}, "2.0": {"compressor_uf": 45, "fan_uf": 3.5, "voltage_rating": 450, "confidence_pct": 68}}' AS jsonb),CAST('{"1.0": {"voltage": "220-240/50/1", "mca": 7.5, "mocp": 20, "fla_typical": 5.8}, "1.5": {"voltage": "220-240/50/1", "mca": 10.5, "mocp": 25, "fla_typical": 8.5}, "2.0": {"voltage": "220-240/50/1", "mca": 14.0, "mocp": 32, "fla_typical": 11.5}}' AS jsonb),'Using statistical defaults — nameplate not found. Verify specs before finalising estimate.','These capacitor defaults apply to NON-INVERTER units ONLY. Inverter compressors have no run capacitor — do not apply cap_uf values to inverter units.');
